.darma-loader-tw-ping-halo { position: relative; display: inline-flex; align-items: center; justify-content: center; width: var(--loader-size, 48px); height: var(--loader-size, 48px); }
.darma-loader-tw-ping-halo .darma-loader-tw-ping-halo__halo { position: absolute; inset: 0; border-radius: 9999px; background: var(--loader-color, #0ea5e9); opacity: .75; animation: darma-loader-tw-ping-halo-twPing calc(var(--loader-speed, 1s) * 1.2) cubic-bezier(0, 0, .2, 1) infinite; }
.darma-loader-tw-ping-halo::after { content: ''; position: relative; width: 56%; height: 56%; border-radius: 9999px; background: var(--loader-color, #0ea5e9); }
@keyframes darma-loader-tw-ping-halo-twPing { 70%, 100% { transform: scale(2.1); opacity: 0; } }

